package com.anitec.backend;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
@Testcontainers
class SessionMigrationTests {
 @Container static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine");
 DriverManagerDataSource database(){String name="sessions_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(new DriverManagerDataSource(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword())).execute("CREATE DATABASE "+name);return new DriverManagerDataSource("jdbc:postgresql://"+postgres.getHost()+":"+postgres.getMappedPort(5432)+"/"+name,postgres.getUsername(),postgres.getPassword());}
 Flyway flyway(DriverManagerDataSource db,String target){return Flyway.configure().dataSource(db).target(target).placeholders(Map.of("admin_email","retired@bootstrap.invalid","admin_password_hash","DISABLED-HISTORICAL-BOOTSTRAP","demo_seed","false")).load();}
 UUID account(JdbcTemplate j){return j.queryForObject("INSERT INTO identity_accounts(email,password_hash,name,last_name,role,status,verified_at,verification_attempts,verification_resends) VALUES (?,'preserved-hash','Test','Session','GANADERO','ACTIVA',now(),3,4) RETURNING id",UUID.class,UUID.randomUUID()+"@example.invalid");}
 @Test void freshInstallationAndIdempotentFlyway(){var db=database();assertThat(flyway(db,"latest").migrate().migrationsExecuted).isEqualTo(16);assertThat(flyway(db,"latest").migrate().migrationsExecuted).isZero();}
 @Test void upgradeFromV14PreservesAccountAndBusinessDataButRevokesLegacyTokens(){var db=database();flyway(db,"14").migrate();var j=new JdbcTemplate(db);var id=account(j);var before=j.queryForMap("SELECT * FROM identity_accounts WHERE id=?",id);j.update("INSERT INTO identity_refresh_tokens(account_id,token_digest,expires_at) VALUES (?, ?, now()+interval '7 days')",id,"a".repeat(64));UUID farm=j.queryForObject("INSERT INTO livestock_farms(farmer_id,name) VALUES (?,'Preserved farm') RETURNING id",UUID.class,id);assertThat(flyway(db,"latest").migrate().migrationsExecuted).isEqualTo(2);assertThat(j.queryForMap("SELECT * FROM identity_accounts WHERE id=?",id)).isEqualTo(before);assertThat(j.queryForObject("SELECT count(*) FROM livestock_farms WHERE id=?",Integer.class,farm)).isEqualTo(1);assertThat(j.queryForObject("SELECT revoked_at IS NOT NULL FROM identity_refresh_tokens WHERE account_id=?",Boolean.class,id)).isTrue();assertThat(j.queryForObject("SELECT count(*) FROM identity_sessions",Integer.class)).isZero();}
 @Test void databaseRejectsOverlongSessionAndDuplicateSuccessor(){var db=database();flyway(db,"latest").migrate();var j=new JdbcTemplate(db);var id=account(j);assertThatThrownBy(()->j.update("INSERT INTO identity_sessions(id,account_id,created_at,expires_at) VALUES (?,?,now(),now()+interval '8 days')",UUID.randomUUID(),id)).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);UUID session=UUID.randomUUID();j.update("INSERT INTO identity_sessions(id,account_id,created_at,expires_at) VALUES (?,?,now(),now()+interval '7 days')",session,id);for(String digest:List.of("a".repeat(64),"b".repeat(64),"c".repeat(64)))j.update("INSERT INTO identity_session_tokens(token_digest,session_id,created_at,expires_at) VALUES (?,?,now(),now()+interval '1 day')",digest,session);j.update("UPDATE identity_session_tokens SET consumed_at=now(),operation_id=?,successor_digest=? WHERE token_digest=?",UUID.randomUUID(),"c".repeat(64),"a".repeat(64));assertThatThrownBy(()->j.update("UPDATE identity_session_tokens SET consumed_at=now(),operation_id=?,successor_digest=? WHERE token_digest=?",UUID.randomUUID(),"c".repeat(64),"b".repeat(64))).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);}

 @Test void absoluteSessionBoundIsIndependentOfDaylightSaving(){var db=database();flyway(db,"latest").migrate();var j=new JdbcTemplate(db);var id=account(j);try(var connection=db.getConnection()){try(var set=connection.createStatement()){set.execute("SET TIME ZONE 'America/New_York'");}try(var insert=connection.prepareStatement("INSERT INTO identity_sessions(id,account_id,created_at,expires_at) VALUES (?,?,TIMESTAMPTZ '2030-03-09 12:00:00-05',TIMESTAMPTZ '2030-03-16 13:00:00-04')")){insert.setObject(1,UUID.randomUUID());insert.setObject(2,id);assertThat(insert.executeUpdate()).isEqualTo(1);}}catch(java.sql.SQLException failure){throw new IllegalStateException("Test session bound failed",failure);}}
}
